class Solution { public:
    int maximumSum(vector<int>& nums) {
        unordered_map<int,int> best; int ans=-1;
        for(int x:nums){int d=0,t=x;while(t){d+=t%10;t/=10;}
            if(best.count(d)) ans=max(ans,x+best[d]);
            best[d]=max(best[d],x);
        }
        return ans;
    }
};
